    const comResgate = { ...cdb, movimentos: [...cdb.movimentos, resgate('m3', '2026-03-20', 20000)] };
    expect(valorEm(comResgate)).toBe(140000);
  });

  it('critério 7: rentabilidade em valor e % com uma casa, e sem divisão por zero', () => {
