    const perda = ativo('p', 'acoes', { movimentos: [aporte('m', '2026-01-01', 30000)], marcacoes: [{ id: 'k', data: '2026-02-01', valor: 20000 }] });
    expect(desempenhoAtivo(perda)).toMatchObject({ rentabilidade: -10000, rentabilidadePct: -33.3 });
